import React, { useState } from "react";
import Dialog, { DialogHeader, DialogActions, DialogContent } from "./Dialog";
import Button from "../Button";
import RadioGroup from "../RadioGroup";
import Radio from "../Radio";
import Stack from "../Stack";
import type { Meta, StoryObj } from "@storybook/react";
import withDarkMode from "../../lib/utils/storybookDecorators";

const meta: Meta<typeof Dialog> = {
  id: "Components/Dialog",
  title: "Components/Dialog",
  component: Dialog,
  argTypes: {
    scroll: {
      control: 'select',
      options: ['dialog', 'body', 'content'],
      defaultValue: 'dialog',
      description: 'Determines the container for scrolling the dialog'
    },
  }
};

export default meta;
type Story = StoryObj<typeof Dialog>;

export const Basic: Story = {
  args: {
    scroll: 'dialog',
  },
  parameters: { docs: { source: { type: "code" }}},
  render: (args) => {
    const [open, setOpen] = useState(false);
    return (
      <React.Fragment>
        <Button
          variant="primary"
          onClick={() => setOpen(true)}
          aria-haspopup="dialog"
        >
          Open dialog
        </Button>
        <Dialog open={open} onClose={() => setOpen(false)} {...args}>
          <DialogHeader>Title</DialogHeader>
          <DialogContent>
            <p>
              Lorem ipsum dolor sit lorem a amet, consectetur adipiscing elit,
              sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.
              Ut enim ad minim veniam.
            </p>
          </DialogContent>
          <DialogActions>
            <Button variant="secondary" onClick={() => setOpen(false)}>
              Cancel
            </Button>
            <Button variant="primary" onClick={() => setOpen(false)}>
              Validate
            </Button>
          </DialogActions>
        </Dialog>
      </React.Fragment>
    );
  },
};

export const Dark: Story = {
  tags: ["visual-test"],
  decorators: [withDarkMode],
  parameters: { docs: { source: { type: "code" }}},
  ...Basic,
};

